from lib import *
S = SS('v30')
steps = [
    step("proxy_pass 末尾的斜杠。上游回显它收到的路径。location /api/ + proxy_pass http://u(无 URI):/api/users?id=1 原样到上游;/api//users 也原样(/api//users)。location /api/ + proxy_pass http://u/:/api/users?id=1 → /users?id=1,/api/ → /,/api//users → /users(合并了斜杠)。location /api/ + proxy_pass http://u/v1/:→ /v1/users?id=1。location /api + proxy_pass http://u/:/api/users → /users,/api → /,但 /apix/y 也被匹配了,变成 /x/y。location /api + proxy_pass http://u/v1:/apix/y → /v1x/y。location /api/ + proxy_pass http://u/v1(末尾没斜杠):/api/users → /v1users,前缀 /api/ 换成了 /v1,没有补斜杠。请求 /api(不带斜杠)在 location /api/ 下由 nginx 回 301 补斜杠,/apix/y 不匹配,404。", t=tl(S(1)), mark=lidx(S(1), 'http://u/v1', '/api + proxy_pass http://u/ '), done=lidx(S(1), 'http://u/v1/', 'location /api/ + proxy_pass http://u  '), b=bars([['u(无 URI):/api/users → ', 1, '/api/users'], ['u/:/api/users → ', 1, '/users'], ['u/v1/:/api/users → ', 1, '/v1/users'], ['u/v1(末尾无斜杠):/api/users → ', 1, '/v1users']], 1, done=[0, 1, 2], mark=[3]), kv=KV([['无 URI', '原样转发'], ['有 URI', '替换匹配的前缀'], ['location /api 没有斜杠', '/apix/y 也匹配,变成 /x/y'], ['u/v1 末尾无斜杠', '/api/users → /v1users']], ['u/v1 末尾无斜杠'])),
    step("rewrite 的标志。location /old/ 里 rewrite ^/old/(.*)$ /new/$1,再 proxy_pass http://u;另有 location /new/ 直接 return。请求 /old/a/b?x=1。没有标志:命中 /new/ 这个 location(nginx 自己回 hit /new/ location),请求没到上游——rewrite 改了 URI 之后,nginx 用新 URI 重新选 location,和 last 一样(我原以为会接着执行 proxy_pass,实测不是)。break:上游收到 /new/a/b?x=1。last:命中 /new/ location。redirect:302,Location 指向 /new/a/b?x=1。permanent:301,同样的 Location。查询串都保留了。", t=tl(S(2)), mark=lidx(S(2), '(无标志)', 'last'), done=lidx(S(2), 'break', 'redirect', 'permanent'), b=bars([['无标志 → 重新选 location', 1, '命中 /new/'], ['last → 重新选 location', 1, '命中 /new/'], ['break → 上游', 1, '/new/a/b?x=1'], ['redirect → client', 302, '302']], 302, mark=[0, 1], done=[2], cur=[3]), kv=KV([['无标志', '等同 last,重新选 location'], ['break', '停在当前 location,继续 proxy_pass'], ['redirect / permanent', '302 / 301,查询串保留']], ['无标志'])),
    step("查询串和路径编码。四个路径:/api/a%20b?q=%41、/api/a%2Fb、/api/x/../y、/api//z。(a) 无 URI 的 proxy_pass:上游收到原样的 /api/a%20b?q=%41、/api/a%2Fb、/api/x/../y、/api//z。(b) proxy_pass http://u/:/a%20b?q=%41、/a/b(%2F 被解码成了真正的斜杠)、/y(.. 被解析掉)、/z(// 合并)。(c) rewrite ... break 再 proxy_pass:结果和 (b) 完全相同。%20 保持编码。网关和上游对路径的理解不一致(上游看到的是 %2F 还是 /),是路径穿越和缓存投毒类问题的来源之一。", t=tl(S(3)), mark=lidx(S(3), '(b)', '(c)'), done=lidx(S(3), '(a)'), b=bars([['(a) /api/a%2Fb → ', 1, '/api/a%2Fb'], ['(b) /api/a%2Fb → ', 1, '/a/b'], ['(a) /api/x/../y → ', 1, '/api/x/../y'], ['(b) /api/x/../y → ', 1, '/y']], 1, done=[0, 2], mark=[1, 3]), kv=KV([['无 URI', '%2F、..、// 原样'], ['有 URI 或 rewrite', '%2F 解码成 /,.. 解析,// 合并'], ['%20', '保持编码']], ['有 URI 或 rewrite'])),
]
A = mkartv('v30', 30, '微服务,网关,nginx,proxy_pass,rewrite,路径重写,真实验证,动画演示',
    '实测 nginx 路径重写:proxy_pass 带 URI 与不带 URI、location 带斜杠与不带斜杠的 6 种组合各得到什么路径(/api/users → /users、/v1users、/x/y);rewrite 无标志等同 last、break 才继续 proxy_pass;带 URI 的 proxy_pass 把 %2F 解码成斜杠。',
    'proxy_pass 末尾多一个斜杠,上游收到的路径会差多少?rewrite 的 last、break 到底怎么走?%2F、.. 和 // 经过网关会变成什么?这篇用回显路径的上游把它们逐格量出来,也纠正了一个我自己预先的想法。',
    [('/v1users', 'location /api/ 配 proxy_pass http://u/v1(末尾没斜杠)时,/api/users 被转发成的路径'), ('/x/y', 'location /api(没有末尾斜杠)配 proxy_pass http://u/ 时,/apix/y 被转发成的路径(它也被匹配了)'), ('/a/b', '带 URI 的 proxy_pass 把 /api/a%2Fb 转发成的路径(不带 URI 时原样是 /api/a%2Fb)')],
    [('proxy_pass 的斜杠', '<p>带 URI 时替换匹配的前缀;不带 URI 时原样转发;末尾有没有斜杠差别很大。</p>'),
     ('rewrite 的标志', '<p>没有标志时改了 URI 就重新选 location(像 last);break 才会继续 proxy_pass。</p>'),
     ('路径的规范化', '<p>带 URI 的 proxy_pass 与 rewrite 之后会解码 %2F、解析 .. 和 //。</p>')],
    steps,
    [ENV_V + '。nginx 是 Homebrew 的 1.31.6;上游是回显请求路径的 Python 服务;请求用原始 socket 发出;我在跑实验前的预期有两处与实测不符:(1) 以为 location /api 配 proxy_pass http://u/ 会产生 //users,实测是 /users;(2) 以为 rewrite 没有标志时会接着执行 proxy_pass,实测等同 last。文章按实测写',
     '没有验证:变量出现在 proxy_pass 里时的 URI 处理规则;正则 location 里 proxy_pass 不能带 URI 的限制;merge_slashes off 的效果;更多的编码字符(%00、%5C、UTF-8);其它网关(Envoy、Traefik)的路径规范化选项'],
    '路径重写')
